{
  "name": "@cravenceiling/opencode-etf",
  "version": "1.0.2",
  "author": "cravenceiling",
  "description": "Opencode exclude these files",
  "license": "MIT",
  "type": "module",
  "main": "dist/index.js",
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun",
    "dev": "bun build src/index.ts --outdir .opencode/plugins --target bun --watch",
    "dev:oc": "nodemon --watch .opencode/plugins --exec \"opencode serve\"",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "files": [
    "dist"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cravenceiling/opencode-etf.git"
  },
  "homepage": "https://github.com/cravenceiling/opencode-etf#readme",
  "devDependencies": {
    "@types/bun": "latest",
    "nodemon": "^3.1.11"
  },
  "peerDependencies": {
    "typescript": "^5"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.34",
    "ignore": "^7.0.5"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "ignore-files"
  ]
}
